lemma Tengoku.LeanTnorms.exists_open_containing_seq_with_compact_closure {x : ℕ → X} {y : X}
    (h : Filter.Tendsto x Filter.atTop (nhds y)) :
    ∃ U, y ∈ U ∧ Set.range x ⊆ U ∧ IsOpen U ∧ IsCompact (closure U)

lemma Tengoku.LeanTnorms.ite_interpolate_uniformContinuous (a b : ℝ) (p q : I) (hab : a < b) :
    UniformContinuous (fun x ↦ if x ≤ a then p else
      if a ≤ x ∧ x ≤ b then interpolate a b p q x else q)

lemma Metric.tendsto_nhdsWithin_of_eqOn {f g : ℝ → I} {s : Set ℝ} {x : ℝ}
    {p : I} (h : Set.EqOn f g s) (hf : Filter.Tendsto f (nhdsWithin x s) (nhds p)) :
    Filter.Tendsto g (nhdsWithin x s) (nhds p)

lemma Tengoku.LeanTnorms.dist_fun_compactSupport_continuousOn_dist_dist {x : ℕ → X} {y : X} {p : ℕ → I} {q : I}
    (hd : StrictAnti (fun n ↦ dist (x n) y)) :
    ContinuousOn (dist_fun_compactSupport x y p q) (Set.Icc (dist (x 0) y) (dist (x 0) y + 1))
